create function touch_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=clock_timestamp(); return new; end $$;
create table families (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null check(length(trim(name))>0), email text not null default '', phone text not null default '');
create trigger families_updated before update on families for each row execute function touch_updated_at();
create table children (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), family_id uuid not null references families(id), name text not null check(length(trim(name))>0), birth_date date, medical_notes text not null default '', medical_reviewed_on date, self_medication boolean not null default false, medication_instructions text not null default '', medication_plan text not null default '', court_order_notes text not null default '', safety_plan text not null default '', reviewed_on date);
create trigger children_updated before update on children for each row execute function touch_updated_at();
create table contacts (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), child_id uuid not null references children(id), name text not null check(length(trim(name))>0), phone text not null check(length(trim(phone))>0), relationship text not null default '', authorised_pickup boolean not null default false, unique(child_id,name), unique(id,child_id));
create trigger contacts_updated before update on contacts for each row execute function touch_updated_at();
create table programmes (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null check(length(trim(name))>0), venue text not null, starts_on date not null, ends_on date not null, status text not null default 'planned' check(status in ('planned','active','closed')), check(ends_on>=starts_on));
create trigger programmes_updated before update on programmes for each row execute function touch_updated_at();
create table sessions (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), programme_id uuid not null references programmes(id), name text not null check(length(trim(name))>0), starts_at timestamptz not null, ends_at timestamptz not null, capacity integer not null check(capacity>0), children_per_staff integer not null default 10 check(children_per_staff>0), offsite boolean not null default false, risk_plan text not null default '', status text not null default 'scheduled' check(status in ('scheduled','completed','cancelled')), check(ends_at>starts_at));
create trigger sessions_updated before update on sessions for each row execute function touch_updated_at();
create table bookings (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), child_id uuid not null references children(id), session_id uuid not null references sessions(id), status text not null default 'confirmed' check(status in ('confirmed','waitlist','cancelled')), consent_on date, notes text not null default '', unique(child_id,session_id), unique(id,child_id));
create trigger bookings_updated before update on bookings for each row execute function touch_updated_at();
create table attendance (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), booking_id uuid not null unique, child_id uuid not null, signed_in_at timestamptz, signed_in_by text, signed_out_at timestamptz, collected_by_id uuid, recorded_by text not null, absence_reason text, foreign key(booking_id,child_id) references bookings(id,child_id), foreign key(collected_by_id,child_id) references contacts(id,child_id), check((signed_in_at is not null and nullif(trim(signed_in_by),'') is not null and absence_reason is null) or (signed_in_at is null and signed_in_by is null and nullif(trim(absence_reason),'') is not null)), check((signed_out_at is null and collected_by_id is null) or (signed_out_at>=signed_in_at and signed_in_at is not null and collected_by_id is not null)), check(length(trim(recorded_by))>0));
create trigger attendance_updated before update on attendance for each row execute function touch_updated_at();
create table staff (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), name text not null check(length(trim(name))>0), first_aid_until date, safety_check_due date, active boolean not null default true);
create trigger staff_updated before update on staff for each row execute function touch_updated_at();
create table roster (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), session_id uuid not null references sessions(id), staff_id uuid not null references staff(id), unique(session_id,staff_id));
create trigger roster_updated before update on roster for each row execute function touch_updated_at();
create table incidents (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), booking_id uuid not null references bookings(id), occurred_at timestamptz not null, location text not null, details text not null, injury text not null default '', treatment text not null default '', staff_id uuid not null references staff(id), parent_informed_at timestamptz, confirmation text not null default '', follow_up_due date, status text not null default 'open' check(status in ('open','closed')), check(parent_informed_at is null or parent_informed_at>=occurred_at));
create trigger incidents_updated before update on incidents for each row execute function touch_updated_at();
create table invoices (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), family_id uuid not null references families(id), name text not null, issued_on date not null, due_on date not null, total_cents bigint not null check(total_cents>=0), paid_cents bigint not null default 0 check(paid_cents>=0 and paid_cents<=total_cents), currency text not null default 'NZD' check(currency in ('NZD','AUD')), status text not null default 'open' check(status in ('open','void')), check(due_on>=issued_on));
create trigger invoices_updated before update on invoices for each row execute function touch_updated_at();
create table drills (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), programme_id uuid not null references programmes(id), occurred_at timestamptz not null, name text not null, notes text not null, recorded_by text not null);
create trigger drills_updated before update on drills for each row execute function touch_updated_at();
create table notes (id uuid primary key default gen_random_uuid(), external_id text unique, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), family_id uuid not null references families(id), name text not null, body text not null, recorded_by text not null);
create trigger notes_updated before update on notes for each row execute function touch_updated_at();

create view session_readiness as
select s.id, p.name as programme, s.name as session, s.starts_at, s.ends_at, s.status, s.capacity, s.children_per_staff,
(select count(*) from bookings b where b.session_id=s.id and b.status='confirmed') as booked,
(select count(*) from bookings b where b.session_id=s.id and b.status='waitlist') as waiting,
(select count(*) from roster r join staff st on st.id=r.staff_id where r.session_id=s.id and st.active) as staff_count,
(select count(*) from roster r join staff st on st.id=r.staff_id where r.session_id=s.id and st.active and st.first_aid_until >= (s.ends_at at time zone 'Pacific/Auckland')::date) as first_aiders,
s.offsite, s.risk_plan
from sessions s join programmes p on p.id=s.programme_id;
create view daily_roll as
select b.id, b.child_id, b.session_id, s.name as session, c.name as child, f.name as family, b.status, s.starts_at, s.ends_at,
a.signed_in_at, a.signed_out_at, a.absence_reason, a.signed_in_by, co.name as collected_by,
case when a.absence_reason is not null then 'absent' when a.signed_out_at is not null then 'collected' when a.signed_in_at is not null then 'on site' else 'unrecorded' end as attendance_state
from bookings b join children c on c.id=b.child_id join families f on f.id=c.family_id join sessions s on s.id=b.session_id
left join attendance a on a.booking_id=b.id left join contacts co on co.id=a.collected_by_id where b.status='confirmed' and s.status<>'cancelled';
create view family_balances as
select f.id,f.name as family,i.currency,count(*) as invoices,sum(i.total_cents-i.paid_cents) as balance_cents,
sum(case when i.due_on<current_date then i.total_cents-i.paid_cents else 0 end) as overdue_cents,min(i.due_on) as earliest_due
from families f join invoices i on i.family_id=f.id where i.status='open' and i.paid_cents<i.total_cents group by f.id,f.name,i.currency;
